# define CPU_SET_S(cpu, setsize, set) \
  ((void) (((cpu) / 8 < (setsize)) ? (((unsigned long *) (set))[__NIJI_CPU_WORD (cpu)] |= __NIJI_CPU_MASK (cpu)) : 0))
# define CPU_CLR_S(cpu, setsize, set) \
  ((void) (((cpu) / 8 < (setsize)) ? (((unsigned long *) (set))[__NIJI_CPU_WORD (cpu)] &= ~__NIJI_CPU_MASK (cpu)) : 0))
# define CPU_ISSET_S(cpu, setsize, set) \
  (((cpu) / 8 < (setsize)) ? ((((const unsigned long *) (set))[__NIJI_CPU_WORD (cpu)] & __NIJI_CPU_MASK (cpu)) != 0) : 0)
# define CPU_COUNT_S(setsize, set) __sched_cpucount (setsize, set)
# define CPU_EQUAL_S(setsize, set1, set2) (__builtin_memcmp ((set1), (set2), (setsize)) == 0)
# define __NIJI_CPU_OP_S(setsize, dest, set1, set2, op) \
  (__extension__ ({ unsigned long *__d = (unsigned long *) (dest); const unsigned long *__a = (const unsigned long *) (set1); \
                    const unsigned long *__b = (const unsigned long *) (set2); size_t __i; \
                    for (__i = 0; __i < (setsize) / sizeof (unsigned long); __i++) __d[__i] = __a[__i] op __b[__i]; \
